import type { SyncTarget } from "@agnostic/core";

/** The mark that says a generated file is agn's to rewrite, naming the file it was made from. */
export function generatedHeader(source: string): string {
  return `<!-- generated by agn sync from ${source}; edit that file, not this one -->`;
}

/**
 * Line 1 of the two instruction files. An HTML comment because harnesses read the raw text and
 * GitHub renders nothing.
 */
export const GENERATED_HEADER = generatedHeader(".ag/instructions.md");

const HEADER_LINE = /^<!-- generated by agn sync from .+; edit that file, not this one -->$/;

const FRONT_MATTER = "---";

/** Claude Code imports another file with `@path`, so the instructions exist in one copy. */
const CLAUDE_IMPORT = "@AGENTS.md";

/**
 * Claude Code's parser wants `---` on line 1, so a file with front matter carries the header on
 * its first body line instead. A header anywhere else is text someone wrote, not agn's mark.
 */
export function isGenerated(text: string): boolean {
  const lines = text.split("\n");
  return HEADER_LINE.test(lines[0] ?? "") || HEADER_LINE.test(lines[bodyStart(lines)] ?? "");
}

/** The line after a leading front-matter block, or line 1 when the file has no block. */
function bodyStart(lines: string[]): number {
  if (lines[0] !== FRONT_MATTER) {
    return 0;
  }
  const close = lines.indexOf(FRONT_MATTER, 1);
  return close === -1 ? 0 : close + 1;
}

/** What goes under the header: the instructions themselves, or Claude Code's import of them. */
export function targetBody(target: SyncTarget, instructions: string): string {
  return target === "AGENTS.md" ? instructions : CLAUDE_IMPORT;
}

/** The bytes of one generated file: the header, a blank line, the body, one trailing LF. */
export function renderTarget(target: SyncTarget, instructions: string): string {
  const body = withoutTrailingNewlines(targetBody(target, instructions));
  return body === "" ? `${GENERATED_HEADER}\n` : `${GENERATED_HEADER}\n\n${body}\n`;
}

export function withoutTrailingNewlines(text: string): string {
  return text.replace(/\n+$/, "");
}
